contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint a, uint b) public payable {
        require(a > 0 && b > 0);
        require(address(this).balance >= a + b);
        c.Deposit{value: a}();
        uint balAfterFirst = c.balances(address(this));
        uint ethAfterFirst = address(c).balance;
        c.Deposit{value: b}();
        uint balAfterSecond = c.balances(address(this));
        uint ethAfterSecond = address(c).balance;
        assert(balAfterFirst == a && ethAfterFirst == a && balAfterSecond == a + b && ethAfterSecond == a + b);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _val) public {
        c.Initialized();
        uint before = c.MinSum();
        bool reverted;
        try c.SetMinSum(_val) { reverted = false; } catch { reverted = true; }
        uint afterV = c.MinSum();
        bool revertedLog;
        try c.SetLogFile(address(this)) { revertedLog = false; } catch { revertedLog = true; }
        assert(reverted && revertedLog && afterV == before && c.MinSum() == before);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint deposit, uint amount) public payable {
        require(address(this).balance >= deposit);
        c.SetMinSum(0);
        c.Deposit{value: deposit}();
        require(deposit >= c.MinSum());
        uint etherBefore = address(c).balance;
        c.Collect(amount);
        assert(address(c).balance + amount == etherBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    bool reject;
    constructor(C _c) { c = _c; }
    function run(uint deposit, uint amount) public payable {
        require(address(this).balance >= deposit);
        require(amount > deposit);
        c.SetMinSum(0);
        c.Deposit{value: deposit}();
        uint balBefore = c.balances(address(this));
        uint etherBefore = address(c).balance;
        reject = true;
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        reject = false;
        assert(reverted && c.balances(address(this)) == balBefore && address(c).balance == etherBefore);
    }
    receive() external payable { if (reject) revert(); }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint deposit, uint a, uint b) public payable {
        require(address(this).balance >= deposit);
        require(deposit > 0);
        require(a + b <= deposit);
        c.SetMinSum(0);
        c.Deposit{value: deposit}();
        uint balBefore = c.balances(address(this));
        uint etherBefore = address(c).balance;
        bool revertedA;
        try c.Collect(a) { revertedA = false; } catch { revertedA = true; }
        bool revertedB;
        try c.Collect(b) { revertedB = false; } catch { revertedB = true; }
        assert(!revertedA && !revertedB && c.balances(address(this)) == balBefore - (a + b) && address(c).balance == etherBefore - (a + b));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint d) public {
        require(d > 0);
        uint beforeLen = c.Log().History.length;
        c.Deposit{value: d}();
        (address sender, , uint val, ) = c.Log().History(c.Log().History.length - 1);
        assert(c.Log().History.length == beforeLen + 1 && sender == address(this) && val == d);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint a, uint b, uint d) public payable {
        require(a > 0 && b > 0 && b <= a && d > 0);
        require(address(this).balance >= a + d);
        c.SetMinSum(0);
        c.Deposit{value: a}();
        c.Collect(b);
        c.Deposit{value: d}();
        assert(address(c).balance == a - b + d && c.balances(address(this)) == a - b + d);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint balBefore, uint d, uint a) public payable {
        require(d > 0 && a > 0 && a <= d);
        c.SetMinSum(d);
        c.Deposit{value: d}();
        balBefore = c.balances(address(this));
        c.Collect(a);
        assert(c.balances(address(this)) == balBefore + d - a);
    }
    receive() external payable {}
}
